<script setup lang="ts">
import type {PdfTemporaryMark} from '../../../shared/contracts';
defineProps<{notes:PdfTemporaryMark[];canExport:boolean;exporting:boolean;exportStatus:string}>();
const emit=defineEmits<{jump:[page:number];remove:[id:string];export:[]}>();
</script>
<template><aside class="pdf-notes" aria-label="本次批注"><h3>本次批注 <span>{{notes.length}}</span></h3><button type="button" class="pdf-export-notes" :disabled="!canExport||exporting" @click="emit('export')">{{exporting?'正在导出…':'导出当前页批注 PNG'}}</button><p v-if="exportStatus" class="pdf-export-status" role="status">{{exportStatus}}</p><p v-if="!notes.length" class="pdf-notes-empty">用鼠标划选页面文字，在工具栏中选择“高亮”或“写备注”。关闭文件后批注会清空；需要留存时可主动导出当前页图片。</p><article v-for="mark in notes" :key="mark.id" class="pdf-note"><div class="pdf-note-head"><button type="button" @click="emit('jump',mark.page)">第 {{mark.page}} 页 · {{mark.kind==='note'?'备注':'高亮'}}</button><button type="button" :aria-label="'删除第 '+mark.page+' 页批注'" @click="emit('remove',mark.id)">删除</button></div><p :title="mark.quote">{{mark.quote}}</p><textarea v-if="mark.kind==='note'" v-model="mark.content" aria-label="批注内容" placeholder="写下备注（仅保存在本次预览）"></textarea></article></aside></template>
